    if (rp.uncovered > 0)
      f3.note(`${sc.label}: ${(rp.uncovered * 100).toFixed(2)} % of the portfolio has neither its own prices nor a proxy for the window and is left at 0 %`);
    if (proxied.length) f3.note(`${sc.label}: proxies used \u2014 ${proxied.join(", ")}`);
