    entry,
    stop,
    riskPct: ctx.profile.limits.riskPerTradePct * ctx.breaker.sizeMultiplier,
    maxPositionPct: ctx.profile.limits.maxPositionPct,
    cash: Math.max(0, (ctx.cashBase - buffer) / ctx.fxToBase),
    lot: crypto ? 1e-5 : 1,
