    symbol: inst.symbol,
    name: inst.name,
    currency: inst.currency,
    order,
    entry,
    stop,
    stopMethod,
    targets,
    atr: a,
    riskPerUnit,
    rewardRisk: targets.map((t) => (t - entry) / riskPerUnit),
    quantity: size.quantity,
    notional: size.notional,
    riskAmount: size.riskAmount,
    riskPct: size.riskPct,
